            half y = (half)((float)a_bn[f] * (float)acc + (float)b_bn[f]);
            y = (a == ACT_RELU) ? reluf(y) : (a == ACT_TANH ? tanhf_fast(y) : sigmoidf(y));
            pool_acc[f] += y;
